export const categories = {
 'Materials': ['Raw Material','Reagent','Solvent','Intermediate','Product','By-product','Waste','Recovered Material','Recycle Material','Process Stream'],
 'Unit operations': ['Mixing','Reaction','Filtration','Centrifugation','Separation','Extraction','Distillation','Crystallization','Drying','Milling','Blending','Granulation','Heating','Cooling','Evaporation','Washing','Transfer','Charging','Dispensing','Storage','Hold','Packaging','Custom Operation'],
 'Equipment': ['Reactor','Mixing Vessel','Tank','Filter','Centrifuge','Dryer','Column','Pump','Heat Exchanger','Mixer','Mill','Granulator','Separator','Storage Vessel','Transfer Line','Custom Equipment'],
 'Flow / logic': ['Split','Merge','Side Stream','Recycle','Bypass','Conditional Path'],
 'Quality': ['Sample Point','IPC','QC','In-Line Analysis','Analytical Test','Specification Check','Hold Point','Release Point'],
 'Documentation': ['Note','Comment','Annotation','Group','Process Area','Phase','Boundary / Container','Reference','Document','Data Output']
};
const descriptions = {'Raw Material':'Starting material entering the process.','Reagent':'Reagent consumed or used in an operation.','Solvent':'Solvent supplied to a process step.','Intermediate':'Material between process operations.','Product':'Classified final process output.','By-product':'Secondary product of an operation.','Waste':'Material routed to treatment or disposal.','Recovered Material':'Material recovered for further use.','Recycle Material':'Material returned to an earlier step.','Process Stream':'A general material stream endpoint.','Mixing':'Combine and mix process materials.','Reaction':'Document a chemical transformation step.','Filtration':'Solid–liquid separation through filtration.','Centrifugation':'Separate materials using a centrifuge.','Separation':'A configurable separation step.','Extraction':'Transfer material between phases.','Distillation':'Document a distillation operation.','Crystallization':'Document formation of crystalline solids.','Drying':'Remove moisture or residual solvent.','Sample Point':'Collect a sample from an associated operation.','IPC':'Document an in-process control.','QC':'Document a quality control reference.','Split':'One incoming stream, multiple outgoing streams.','Merge':'Multiple incoming streams, one outgoing stream.','Recycle':'Return a stream to an earlier operation.','Note':'Free-form process documentation.','Group':'A resizable visual container for related elements.'};
const familyByCategory=['material','operation','equipment','logic','quality','documentation'];
export const definitions = Object.fromEntries(Object.entries(categories).flatMap(([category,types],idx)=>types.map(label=>{
 const type=label.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/-$/,'');
 const family=familyByCategory[idx],container=['Group','Process Area','Phase','Boundary / Container'].includes(label);
 return [type,{type,category,label,family,container,description:descriptions[label]||`Document ${label.toLowerCase()}${family==='equipment'?' equipment and its specifications':family==='operation'?' as a process operation':''}.`,ports:container?[]:['left','right','top','bottom'],width:container?440:family==='material'?144:family==='logic'?104:196,height:container?260:family==='material'?112:family==='logic'?92:90,defaults:{name:label,description:'',notes:'',material:'',phase:'',quantity:'',unit:'',equipmentId:'',equipmentType:'',capacity:'',reference:'',classification:label==='Product'?'Product':label==='Waste'?'Waste':'',test:'',condition:'',requiredFields:'',additional:{},accent:'default'}}];
})));
export const streamTypes=['Process','Intermediate','Product','Waste','Recycle','Side stream','Solvent','Utility','Sample'];
export const linkTypes=['Main Process Flow','Material Flow','Side Stream','Recycle','Sampling / Analytical Link','Information / Data Link'];
export function icon(type,size=20){
 const def=definitions[type];let name=type;
 if(def?.family==='material'&&!['solvent','waste','recycle-material','product'].includes(type))name='hex';
 if(def?.family==='quality')name=['qc','ipc','analytical-test'].includes(type)?'flask':'sample';
 const paths={hex:'<path d="m12 2 8.7 5v10L12 22l-8.7-5V7Z"/><path d="m8 9 4-2 4 2v6l-4 2-4-2Z"/>',mixing:'<path d="M7 3h10M12 3v13M5 8v11c0 3 14 3 14 0V8M8 16l8-3M8 13l8 3"/>',reaction:'<path d="M9 2h6M10 2v6L4 18a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3L14 8V2M7 15h10"/><path d="m10 12 2 1 2-2"/>',filtration:'<path d="M3 4h18v3l-7 8v5l-4 2v-7L3 7ZM3 8h18M7 11h10"/>',drying:'<path d="M4 11h16v9H4ZM8 7c-3-3 3-3 0-6M12 7c-3-3 3-3 0-6M16 7c-3-3 3-3 0-6M7 16h10"/>',solvent:'<path d="M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13ZM8 15a4 4 0 0 0 4 4"/>',waste:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',product:'<path d="m12 2 8.7 5v10L12 22l-8.7-5V7Z"/><path d="m8 12 3 3 5-6"/>','recycle-material':'<path d="m4 9 2-4a3 3 0 0 1 5 0l2 3M4 4v5h5M17 7l3 5a3 3 0 0 1-3 4h-2M21 15l-5 2 1-5M12 21H6a3 3 0 0 1-2-5l1-2M8 18l-3-4-3 4"/>',flask:'<path d="M9 3h6M10 3v6L5 18a2 2 0 0 0 2 3h10a2 2 0 0 0 2-3l-5-9V3M8 15h8"/>',sample:'<path d="m15 3 6 6M17 5 5 17a3 3 0 0 0 4 4L21 9M8 14l4 4"/>',distillation:'<path d="M8 2v20M16 2v20M8 4h8M8 9h8M8 14h8M8 19h8M4 6h4M16 17h4"/>',tank:'<ellipse cx="12" cy="5" rx="7" ry="3"/><path d="M5 5v14c0 4 14 4 14 0V5M5 18c0 4 14 4 14 0"/>',split:'<path d="M12 3v7M12 10H5v11M12 10h7v11M2 18l3 3 3-3M16 18l3 3 3-3"/>',merge:'<path d="M5 3v8h14V3M12 11v10M9 18l3 3 3-3"/>',note:'<path d="M4 3h16v13l-5 5H4ZM15 21v-5h5M8 8h8M8 12h6"/>',group:'<rect x="3" y="3" width="18" height="18" rx="2" stroke-dasharray="3 3"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',chevron:'<path d="m8 10 4 4 4-4"/>',arrow:'<path d="M4 12h16M15 7l5 5-5 5"/>',cursor:'<path d="m5 3 14 10-7 1-4 7Z"/>',hand:'<path d="M8 12V5a2 2 0 0 1 4 0v7-9a2 2 0 0 1 4 0v9-6a2 2 0 0 1 4 0v9c0 8-10 9-13 5l-5-7c-1-3 2-4 4-1l2 2"/>',connect:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M5 7v8a4 4 0 0 0 4 4h8"/>',undo:'<path d="M8 4 3 9l5 5M3 9h11a6 6 0 0 1 0 12"/>',redo:'<path d="m16 4 5 5-5 5M21 9H10a6 6 0 0 0 0 12"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2M12 21v2M1 12h2M21 12h2M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2"/>',moon:'<path d="M21 13a9 9 0 1 1-10-10 7 7 0 0 0 10 10Z"/>',check:'<path d="m5 12 4 4L19 6"/>',validate:'<path d="m12 2 8 3v7c0 6-8 10-8 10S4 18 4 12V5Z"/><path d="m8 11 3 3 5-6"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',folder:'<path d="M3 7V4h6l3 3h9v14H3ZM3 11h18"/>',save:'<path d="M4 3h13l4 4v14H3V3ZM7 3v6h9V3M7 21v-8h10v8"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',fit:'<path d="M3 9V3h6M15 3h6v6M21 15v6h-6M9 21H3v-6"/>',grid:'<path d="M8 3v18M16 3v18M3 8h18M3 16h18"/>',panel:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',trash:'<path d="M3 6h18M5 6l1 15h12l1-15M9 6V3h6v3M10 10v7M14 10v7"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5M12 16v2"/>',warning:'<path d="m12 3 10 18H2ZM12 9v5M12 17v1"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',vertical:'<path d="M12 3v18M8 7l4-4 4 4M8 17l4 4 4-4"/>',horizontal:'<path d="M3 12h18M7 8l-4 4 4 4M17 8l4 4-4 4"/>',layers:'<path d="m12 2 10 6-10 6L2 8ZM2 12l10 6 10-6M2 16l10 6 10-6"/>'};
 if(!paths[name])name=def?.family==='equipment'?'tank':def?.family==='documentation'?'note':def?.family==='logic'?'split':def?.family==='operation'?'mixing':'hex';
 return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`;
}
